// Generates server.wat, a test plugin for the plugin platform section of tests/http/e2e.sh:
//   node tests/fixtures/plugin-ext/gen.mjs
// Each rule: when the input contains `needle`, answer with `reply`, or send `host` to the
// `bf.request` host function and return its answer inside {"json": ...}.
import { writeFileSync } from "node:fs";

const db = (o) => JSON.stringify({ op: "db", ...o });
const TOPIC = 2; // "Best casino in town", an open public topic by the time e2e gets here
const path = (p) => `"path":"${p}"`;
const rules = [
  { needle: '"hook":"job.run"', host: db({ action: "insert", table: "notes", values: { body: "from-job" } }), plain: true },
  { needle: path("db-insert"), host: db({ action: "insert", table: "notes", values: { body: "hello" } }) },
  { needle: path("db-select"), host: db({ action: "select", table: "notes", order: "id" }) },
  { needle: path("db-users"), host: db({ action: "select", table: "users" }) },
  { needle: path("read"), host: JSON.stringify({ op: "content.read", topic: TOPIC }) },
  { needle: path("read-missing"), host: JSON.stringify({ op: "content.read", topic: 999999 }) },
  { needle: path("reply"), host: JSON.stringify({ op: "content.reply", topic: TOPIC, body: "Bot says hello" }) },
  { needle: path("job"), host: JSON.stringify({ op: "job", payload: { n: 1 } }) },
  { needle: path("notify"), host: JSON.stringify({ op: "notify", user_ids: [1], text: "Plugin says hi", url: "/latest" }) },
  { needle: path("notify-evil"), host: JSON.stringify({ op: "notify", user_ids: [1], text: "x", url: "//evil.test" }) },
  { needle: path("kv-set"), kv: ["k", "v"] },
  { needle: path("http-get"), http: "http://127.0.0.1:9911/hook-log" },
  { needle: path("http-other"), http: "http://localhost:9911/hook-log" },
  { needle: "ext-cook", reply: JSON.stringify({ data: { html: '<p class="ext-cooked">cooked</p><script>alert(5)</script>' } }) },
  { needle: '"hook":"panel.render"', reply: JSON.stringify({ html: '<b class="ext-panel">panel</b><script>alert(6)</script>' }) },
  { needle: '"hook":"widget.render"', reply: JSON.stringify({ html: '<i class="ext-widget">w</i><script>alert(7)</script>' }) },
  { needle: '"hook":"api.serialize"', reply: JSON.stringify({ fields: { score: 42 } }) },
  { needle: '"hook":"member.filter"', reply: JSON.stringify({ user_ids: [2, 1] }) },
  { needle: '"hook":"login.begin"', reply: JSON.stringify({ redirect: "https://idp.example/start" }) },
  { needle: '"hook":"login.callback"', reply: JSON.stringify({ subject: "ext-77", email: "extlogin@example.com", email_verified: true, name: "extlogin" }) },
  { needle: '"hook":"sitemap.urls"', reply: JSON.stringify({ urls: ["/ext-page", "//evil.test/x"] }) },
];

let at = 16;
const data = [];
const put = (s) => {
  const off = at;
  const len = Buffer.byteLength(s);
  data.push(`  (data (i32.const ${off}) "${[...Buffer.from(s)].map((b) => "\\" + b.toString(16).padStart(2, "0")).join("")}")`);
  at += len + 1;
  return [off, len];
};
const packed = ([o, l]) => `(i64.or (i64.shl (i64.const ${o}) (i64.const 32)) (i64.const ${l}))`;
const empty = put("{}");
const denied = put('{"status":403,"json":null}');
const open = put('{"json":');
const close = put("}");

const branches = rules.map((r) => {
  const [no, nl] = put(r.needle);
  const test = `(call $find (local.get $p) (local.get $n) (i32.const ${no}) (i32.const ${nl}))`;
  if (r.kv) {
    const [ko, kl] = put(r.kv[0]);
    const [vo, vl] = put(r.kv[1]);
    return `    (if ${test} (then (if (i32.lt_s (call $kv_set (i32.const ${ko}) (i32.const ${kl}) (i32.const ${vo}) (i32.const ${vl})) (i32.const 0)) (then (return ${packed(denied)}))) (return ${packed(empty)})))`;
  }
  if (r.http) {
    const [uo, ul] = put(r.http);
    return `    (if ${test} (then (return (call $wrap (call $http_get (i32.const ${uo}) (i32.const ${ul}))))))`;
  }
  if (r.reply) return `    (if ${test} (then (return ${packed(put(r.reply))})))`;
  const [ho, hl] = put(r.host);
  const call = `(call $request (i32.const ${ho}) (i32.const ${hl}))`;
  if (r.plain) return `    (if ${test} (then (drop ${call}) (return ${packed(empty)})))`;
  return `    (if ${test} (then (return (call $wrap ${call}))))`;
});

const wat = `;; Generated by gen.mjs. Do not edit.
(module
  (import "bf" "request" (func $request (param i32 i32) (result i64)))
  (import "bf" "http_get" (func $http_get (param i32 i32) (result i64)))
  (import "bf" "kv_set" (func $kv_set (param i32 i32 i32 i32) (result i32)))
  (memory (export "memory") 4)
  (global $top (mut i32) (i32.const ${Math.max(at + 16, 16384)}))
${data.join("\n")}
  (func $alloc (export "alloc") (param $n i32) (result i32)
    (local $p i32)
    (local.set $p (global.get $top))
    (global.set $top (i32.add (global.get $top) (local.get $n)))
    (local.get $p))
  (func $find (param $h i32) (param $hl i32) (param $nd i32) (param $nl i32) (result i32)
    (local $i i32) (local $j i32)
    (block $no
      (loop $outer
        (br_if $no (i32.gt_s (i32.add (local.get $i) (local.get $nl)) (local.get $hl)))
        (local.set $j (i32.const 0))
        (block $miss
          (loop $inner
            (br_if $miss (i32.ne (i32.load8_u (i32.add (i32.add (local.get $h) (local.get $i)) (local.get $j)))
                                 (i32.load8_u (i32.add (local.get $nd) (local.get $j)))))
            (local.set $j (i32.add (local.get $j) (i32.const 1)))
            (br_if $inner (i32.lt_s (local.get $j) (local.get $nl)))
            (return (i32.const 1))))
        (local.set $i (i32.add (local.get $i) (i32.const 1)))
        (br $outer)))
    (i32.const 0))
  ;; Host answer (ptr << 32 | len) to {"json":<answer>}; -1 becomes a 403.
  (func $wrap (param $r i64) (result i64)
    (local $src i32) (local $len i32) (local $out i32)
    (if (i64.le_s (local.get $r) (i64.const 0)) (then (return ${packed(denied)})))
    (local.set $src (i32.wrap_i64 (i64.shr_u (local.get $r) (i64.const 32))))
    (local.set $len (i32.wrap_i64 (local.get $r)))
    (local.set $out (call $alloc (i32.add (local.get $len) (i32.const ${open[1] + close[1]}))))
    (memory.copy (local.get $out) (i32.const ${open[0]}) (i32.const ${open[1]}))
    (memory.copy (i32.add (local.get $out) (i32.const ${open[1]})) (local.get $src) (local.get $len))
    (memory.copy (i32.add (i32.add (local.get $out) (i32.const ${open[1]})) (local.get $len)) (i32.const ${close[0]}) (i32.const ${close[1]}))
    (i64.or (i64.shl (i64.extend_i32_u (local.get $out)) (i64.const 32))
            (i64.extend_i32_u (i32.add (local.get $len) (i32.const ${open[1] + close[1]})))))
  (func (export "handle") (param $p i32) (param $n i32) (result i64)
${branches.join("\n")}
    ${packed(empty)}))
`;
writeFileSync(new URL("server.wat", import.meta.url), wat);
